/* y[i] = x[i] * recip(sum of x), exactly as the oracle renders
   store %y (mul %v (expand (recip (reduce %v op=add)))):
   the sum folds left to right from x[0], the reciprocal is computed once
   as 1.0f / sum, and each element is multiplied by it. n >= 1.
   Results are compared bit for bit (printed as hex bits). */
void normalize(const float *x, float *y, int n) {
  float s = 0.0f;
  for (int i = 0; i < n; i++) s += x[i];
  for (int i = 0; i < n; i++) y[i] = x[i] / s;
}
